export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export const MAX_BODY_BYTES = 64 * 1024;
const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);
export const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

const isPlainObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

/** True when the media type of a Content-Type header is application/json. */
export function isJsonContentType(contentType: string | undefined): boolean {
  if (!contentType) return false;
  return contentType.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

function integerField(body: Record<string, unknown>, name: string, min: number, max: number, fallback: number, errors: FieldError[]): number {
  const v = body[name];
  if (v === undefined) return fallback;
  if (typeof v !== 'number' || !Number.isInteger(v)) {
    errors.push({ field: name, message: 'must be an integer' });
  } else if (v < min || v > max) {
    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
  } else {
    return v;
  }
  return fallback;
}

/** Parses and validates a submission body. Returns every offending field, not just the first. */
export function parseSubmission(raw: string): { value?: Submission; errors: FieldError[] } {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return { errors: [{ field: 'body', message: 'must be valid JSON' }] };
  }
  if (!isPlainObject(parsed)) return { errors: [{ field: 'body', message: 'must be a JSON object' }] };

  const errors: FieldError[] = [];
  for (const key of Object.keys(parsed)) {
    if (!KNOWN_FIELDS.has(key)) errors.push({ field: key, message: 'is not a recognised field' });
  }

  let input = '';
  const rawInput = parsed.input;
  if (rawInput === undefined) {
    errors.push({ field: 'input', message: 'is required' });
  } else if (typeof rawInput !== 'string') {
    errors.push({ field: 'input', message: 'must be a string' });
  } else if (rawInput.length < 1 || rawInput.length > 1000) {
    errors.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  } else if (rawInput.trim() === '') {
    errors.push({ field: 'input', message: 'must not be only whitespace' });
  } else {
    input = rawInput;
  }

  const steps = integerField(parsed, 'steps', 1, 20, 5, errors);
  const failAttempts = integerField(parsed, 'failAttempts', 0, 5, 0, errors);

  if (errors.length > 0) return { errors };
  return { value: { input, steps, failAttempts }, errors };
}

