import { setInterval as every, setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { HEARTBEAT_INTERVAL_MS, MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, type JobRow } from './jobs.ts';

const POLL_MS = 200;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function heartbeat(): void {
  db.prepare(
    "INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at",
  ).run(Date.now());
}

/** A job left "running" by a worker that died is queued again; its interrupted attempt is not resumed. */
function requeueInterrupted(): void {
  const changed = db
    .prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'")
    .run(new Date().toISOString());
  if (Number(changed.changes) > 0) console.log(`requeued ${changed.changes} interrupted job(s)`);
}

/** Takes the oldest queued job that is due and starts an attempt on it, in one transaction. */
function claimNext(): JobRow | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db
      .prepare("SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1")
      .get(Date.now()) as unknown as JobRow | undefined;
    if (!row) {
      db.exec('COMMIT');
      return undefined;
    }
    db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE seq = ?",
    ).run(new Date().toISOString(), row.seq);
    db.exec('COMMIT');
    return { ...row, status: 'running', attempts: row.attempts + 1, progress_completed: 0 };
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

function setQueued(id: string, runAfter: number): void {
  db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ?").run(
    runAfter,
    new Date().toISOString(),
    id,
  );
}

function setFailed(id: string, error: string): void {
  db.prepare("UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE id = ?").run(
    error,
    new Date().toISOString(),
    id,
  );
}

function setProgress(id: string, completed: number): void {
  db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?').run(completed, new Date().toISOString(), id);
}

function setCompleted(id: string, output: string, steps: number): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = ?, error = NULL, updated_at = ? WHERE id = ?",
  ).run(output, steps, new Date().toISOString(), id);
}

/** Runs one attempt. `job.attempts` already counts this attempt. */
async function runAttempt(job: JobRow): Promise<void> {
  // Simulated transient failure: fails at the first step, before any progress.
  if (job.attempts <= job.fail_attempts) {
    if (job.attempts >= MAX_ATTEMPTS) setFailed(job.id, 'transient failure');
    else setQueued(job.id, Date.now() + RETRY_DELAY_MS);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Give the job back so that it is picked up again on the next start.
      setQueued(job.id, 0);
      return;
    }
    setProgress(job.id, step);
  }
  setCompleted(job.id, job.input.toUpperCase(), job.steps);
}

requeueInterrupted();
heartbeat();
const beats = every(HEARTBEAT_INTERVAL_MS);
void (async () => {
  for await (const _ of beats) {
    if (stopping) break;
    heartbeat();
  }
})();

console.log('worker started');
while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = claimNext();
  } catch (e) {
    console.error('claim failed:', e);
    await sleep(POLL_MS);
    continue;
  }
  if (!job) {
    await sleep(POLL_MS);
    continue;
  }
  try {
    await runAttempt(job);
  } catch (e) {
    console.error(`attempt on job ${job.id} failed:`, e);
    await sleep(POLL_MS);
  }
}

beats.return?.(undefined);
db.prepare("DELETE FROM heartbeats WHERE name = 'worker'").run();
db.close();
console.log('worker stopped');
process.exit(0);

