function setFailed(id: string, error: string): void {
  db.prepare("UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE id = ?").run(
    error,
    new Date().toISOString(),
    id,
  );
}

function setProgress(id: string, completed: number): void {
  db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?').run(completed, new Date().toISOString(), id);
}

function setCompleted(id: string, output: string, steps: number): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = ?, error = NULL, updated_at = ? WHERE id = ?",
  ).run(output, steps, new Date().toISOString(), id);
}

/** Runs one attempt. `job.attempts` already counts this attempt. */
async function runAttempt(job: JobRow): Promise<void> {
  // Simulated transient failure: fails at the first step, before any progress.
  if (job.attempts <= job.fail_attempts) {
    if (job.attempts >= MAX_ATTEMPTS) setFailed(job.id, 'transient failure');
    else setQueued(job.id, Date.now() + RETRY_DELAY_MS);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Give the job back so that it is picked up again on the next start.
      setQueued(job.id, 0);
      return;
    }
    setProgress(job.id, step);
  }
  setCompleted(job.id, job.input.toUpperCase(), job.steps);
}

requeueInterrupted();
heartbeat();
const heartbeatTimer = setInterval(heartbeat, HEARTBEAT_INTERVAL_MS);

console.log('worker started');
while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = claimNext();
  } catch (e) {
    console.error('claim failed:', e);
    await sleep(POLL_MS);
    continue;
  }
  if (!job) {
    await sleep(POLL_MS);
    continue;
  }
  try {
    await runAttempt(job);
  } catch (e) {
    console.error(`attempt on job ${job.id} failed:`, e);
    await sleep(POLL_MS);
  }
}

clearInterval(heartbeatTimer);
db.prepare("DELETE FROM heartbeats WHERE name = 'worker'").run();
db.close();
console.log('worker stopped');
process.exit(0);

import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { HEARTBEAT_STALE_MS, toJob, type JobRow } from './jobs.ts';
import {
  IDEMPOTENCY_KEY_RE,
  MAX_BODY_BYTES,
  isJsonContentType,
  parseSubmission,
  type FieldError,
  type Submission,
} from './validate.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], headers?: Record<string, string>): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } }, headers);
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.', undefined, { allow: allowed.join(', ') });
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function getJobRow(id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

type CreateOutcome = { kind: 'created' | 'replayed'; row: JobRow } | { kind: 'conflict' };

/** Creates a job, or replays/conflicts with an earlier submission that used the same Idempotency-Key. */
function createJob(sub: Submission, key: string | undefined): CreateOutcome {
  const fingerprint = JSON.stringify([sub.input, sub.steps, sub.failAttempts]);
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const existing = db.prepare('SELECT fingerprint, job_id FROM idempotency_keys WHERE key = ?').get(key) as unknown as
        | { fingerprint: string; job_id: string }
        | undefined;
      if (existing) {
        db.exec('COMMIT');
        if (existing.fingerprint !== fingerprint) return { kind: 'conflict' };
        const row = getJobRow(existing.job_id);
        if (!row) throw new Error(`idempotency key ${key} refers to missing job ${existing.job_id}`);
        return { kind: 'replayed', row };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, run_after, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?)`,
    ).run(id, sub.input, sub.steps, sub.failAttempts, now, now);
    if (key !== undefined) {
      db.prepare('INSERT INTO idempotency_keys (key, fingerprint, job_id) VALUES (?, ?, ?)').run(key, fingerprint, id);
    }
    db.exec('COMMIT');
    return { kind: 'created', row: getJobRow(id)! };
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const errors: FieldError[] = [];
  let submission: Submission | undefined;

  if (!isJsonContentType(req.headers['content-type'])) {
    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (tooLarge) {
    errors.push({ field: 'body', message: `must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    const parsed = parseSubmission(text);
    errors.push(...parsed.errors);
    submission = parsed.value;
  }

  const key = req.headers['idempotency-key'];
  if (key !== undefined && !IDEMPOTENCY_KEY_RE.test(key)) {
    errors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  if (errors.length > 0 || !submission) {
    return sendError(res, 400, 'invalid_request', 'The submission is invalid.', errors);
  }

  const outcome = createJob(submission, key);
  if (outcome.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.kind === 'created' ? 201 : 200, toJob(outcome.row));
}

function workerIsUp(): boolean {
  const hb = db.prepare("SELECT at FROM heartbeats WHERE name = 'worker'").get() as unknown as { at: number } | undefined;
  return hb !== undefined && Date.now() - Number(hb.at) < HEARTBEAT_STALE_MS;
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method === 'HEAD' ? 'GET' : (req.method ?? '');

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    return send(res, 200, { status: 'ok', worker: workerIsUp() ? 'up' : 'down' });
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(method === 'GET' && req.method === 'HEAD' ? undefined : uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    const row = getJobRow(match[1]!);
    if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
    return send(res, 200, toJob(row));
  }
  sendError(res, 404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT || 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  const finish = () => {
    db.close();
    process.exit(0);
  };
  server.close(finish);
  server.closeAllConnections();
  setTimeout(finish, 2000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

